"""
jzt 广告诊断**知识层**：问题库 / 3×3 决策表 / 阈值。

来源：《广告投放商家自查指南》(JoySpace pageId aPN441mPvgY5cEmOHIbL) + 京喜实战沉淀，
原为独立 skill `jx-ad-diagnose` 的 `knowledge/03、04`，2026-08-04 打散并入 blacklight。

**为什么放代码里而不是 md**：这些条目要被 `diagnose.py` 的结论直接引用（finding 带编号），
也要能被工具查询（`jzt_ad_playbook`）。放 md 只能靠人读、不能保证结论和依据对得上。
叙述性的部分（口径定义/渠道地图/SKU 下探链路）仍在 `docs/jzt/NOTES_playbook.md`。
—— 与 `yx/stacking.py` 同一模式：**数据进代码可查询，详版留 docs**。

⚠️阈值多为**经验/相对值**。能拿类目基准就别用绝对值；这里的默认值来自日均预算
200~5000 的商家样本，换账户量级要重估。
"""
from __future__ import annotations

from typing import Optional

# --------------------------------------------------------------------------- #
# 一、阈值（`diagnose.py` 的默认参数都从这里取，别在两处各写一份）
# --------------------------------------------------------------------------- #
TH = {
    "balance_ratio": 3.0,      # 余额/单日总预算 达标线（建议 3~5x）
    "plan_budget_low": 100.0,  # 单计划日预算过低线（快车单计划最低 50）
    "spend_slow": 0.5,         # 消耗/预算 < 此值 = 花不动
    "spend_capped": 0.95,      # 消耗/预算 ≥ 此值 = 撞线
    "funnel_dev": 0.2,         # 漏斗层偏离基准超过此比例才算瓶颈
    "roi_attain_low": 0.8,     # 3×3 表：达成/目标 < 0.8 为"未达成"列
    "roi_attain_high": 1.2,    # 3×3 表：达成/目标 > 1.2 为"超预期"列
    "thin_margin_ratio": 1.3,  # 达成ROI/保本ROI ≤ 此值 = 薄利，**禁止降目标**
    "safe_cut_ratio": 1.5,     # 达成ROI/保本ROI > 此值 才考虑降目标换量
    "spend_jump": 0.40,        # 日环比 消耗/CPC 突增线
    "rate_drop": 0.30,         # 日环比 CTR/CVR/ROI 断崖线
    "dead_spend": 50.0,        # 断投预警：昨日消耗≥此值今日掉零才报
}

# --------------------------------------------------------------------------- #
# 二、问题库（编号 → 症状/根因/动作）。诊断结论一律引用编号，便于回溯。
# --------------------------------------------------------------------------- #
def _p(code, title, symptom, cause, action, note=""):
    return {"code": code, "title": title, "症状": symptom, "根因": cause, "动作": action,
            **({"备注": note} if note else {})}


