def problem(code: str) -> dict:
    """按编号取一条。找不到返回 {}。"""
    return PROBLEMS.get((code or "").strip().upper(), {})


def search(keyword: str = "", prefix: str = "") -> dict:
    """按关键词/编号前缀查问题库。keyword 在 标题/症状/根因/动作 里全文匹配。"""
    kw = (keyword or "").strip()
    pf = (prefix or "").strip().upper()
    hits = []
    for c, p in PROBLEMS.items():
        if pf and not c.startswith(pf):
            continue
        if kw and kw not in "".join(str(v) for v in p.values()):
            continue
        hits.append(p)
    hits.sort(key=lambda x: x["code"])
    return {"count": len(hits), "分类": dict(GROUPS), "rows": hits}


