# --------------------------------------------------------------------------- #
# 四、★薄利护栏（实战反馈修正 QZ5）—— 决定"能不能降目标 ROI"的唯一判据
# --------------------------------------------------------------------------- #
def thin_margin_guard(attained_roi: Optional[float], breakeven_roi: Optional[float]) -> dict:
    """**降目标 ROI 之前必须过这道闸**。

    QZ5 里「花不动就降 ROI 扩量」有个大前提：**离保本 ROI 还有足够空间**。
    京喜百补类目毛利率要按**到手价**算（不是京东价），收纳类实测到手价毛利率中位仅 ~16%
    → 保本 ROI ~6.25，护栏很薄。这种薄利品上，**高目标 ROI（10~12）往往是刻意的护栏、不是设错**：
    降目标会「花钱飞快 + 达成 ROI 跳水」，很容易把达成打到保本线下变亏损。

    返回 {ratio, 可降目标, 结论}。`ratio` = 达成ROI / 保本ROI：
      > 1.5  → 有空间，花不动才考虑小幅降目标换量
      ≤ 1.3  → **薄利，别降，宁可花不动**（花不动在薄利品上是"保命"不是"病"）
      中间   → 边际，最多降 5% 并紧盯
    """
    if not attained_roi or not breakeven_roi:
        return {"ratio": None, "可降目标": None,
                "结论": "缺达成ROI或保本ROI，无法判断护栏厚度——**先把到手价口径毛利率取到**再谈调目标。"}
    ratio = round(attained_roi / breakeven_roi, 2)
    if ratio > TH["safe_cut_ratio"]:
        return {"ratio": ratio, "可降目标": True,
                "结论": f"达成ROI 是保本的 {ratio}x（>{TH['safe_cut_ratio']}），护栏够厚 → 花不动可小幅降目标换量"}
    if ratio <= TH["thin_margin_ratio"]:
        return {"ratio": ratio, "可降目标": False,
                "结论": f"达成ROI 仅为保本的 {ratio}x（≤{TH['thin_margin_ratio']}）→ **薄利，禁止降目标**。"
                        f"花不动是护栏在起作用，不是病。真亏/薄利应**升目标 ROI 或优化品/关停**"}
    return {"ratio": ratio, "可降目标": "谨慎",
            "结论": f"达成ROI 是保本的 {ratio}x，处于边际（{TH['thin_margin_ratio']}~{TH['safe_cut_ratio']}）"
                    f"→ 最多降 5% 并紧盯达成，一跌破保本立刻回调"}


def breakeven_roi(gross_margin: Optional[float]) -> Optional[float]:
    """保本 ROI = 1 / 毛利率。⚠️**毛利率必须用到手价口径**（不是京东价），
    否则会高估护栏厚度、给出反向建议（见 NOTES_playbook.md 盈亏口径优先级）。"""
    if not gross_margin or gross_margin <= 0:
        return None
    return round(1.0 / gross_margin, 2)
